import { Fragment, useEffect } from "react";
import Breadcrumbs from "@components/breadcrumbs";
import { Button, Col, Input, Label, Row, FormFeedback } from "reactstrap";
import useSubscribers from "../../../hooks/use_subscribers";
import CustomButton from "../../../components/button";
import formatHelper from "../../../helper/format_helper";
import { MdDragIndicator } from "react-icons/md";
import { DragDropContext, Droppable, Draggable } from "react-beautiful-dnd";
import { FaRegTrashAlt } from "react-icons/fa";
import SliceComponent from "./components/slice";
import Select from "react-select";
import { selectThemeColors } from "@utils";
import {
  OPERATOR_DETERMINED_BARRING,
  SUBSCRIBER_STATUS,
  UNITS,
  USIM_TYPES,
} from "../../../utility/Utils";

const NewSubscriber = () => {
  const {
    createSubscriberController,
    handleValidateForm,
    validations,
    showValidations,
    loadings,
  } = useSubscribers();

  const handleDragEnd = (result) => {
    const { source, destination } = result;

    // If dropped outside the list, do nothing
    if (!destination) return;

    // Reorder the msisdn array
    const reordered = Array.from(createSubscriberController.values.msisdn);
    const [removed] = reordered.splice(source.index, 1);
    reordered.splice(destination.index, 0, removed);

    createSubscriberController.setFieldValue("msisdn", reordered);
  };

  const handleDragSlice = (result) => {
    const { source, destination } = result;
    if (!destination) return;
    const reordered = Array.from(createSubscriberController.values.slice);
    const [removed] = reordered.splice(source.index, 1);
    reordered.splice(destination.index, 0, removed);

    createSubscriberController.setFieldValue("slice", reordered);
  };

  const handleDragSession = (result, arrayIndex) => {
    let prevSliceArray = [...createSubscriberController.values.slice];

    const { source, destination } = result;
    if (!destination) return;
    const reordered = Array.from(prevSliceArray[arrayIndex].session);
    const [removed] = reordered.splice(source.index, 1);
    reordered.splice(destination.index, 0, removed);
    prevSliceArray[arrayIndex].session = reordered;
    createSubscriberController.setFieldValue("slice", prevSliceArray);
  };

  const handleDragPccRule = (result, sliceIndex, sessionIndex) => {
    let prevSliceArray = [
      ...createSubscriberController.values.slice[sliceIndex].session[
        sessionIndex
      ].pcc_rule,
    ];

    const { source, destination } = result;
    if (!destination) return;
    const reordered = Array.from(prevSliceArray);
    const [removed] = reordered.splice(source.index, 1);
    reordered.splice(destination.index, 0, removed);
    prevSliceArray = reordered;
    createSubscriberController.setFieldValue(
      `slice[${sliceIndex}].session[${sessionIndex}].pcc_rule`,
      prevSliceArray
    );
  };

  const handleDragFlow = (result, sliceIndex, sessionIndex, ruleIndex) => {
    let prevSliceArray = [
      ...createSubscriberController.values.slice[sliceIndex].session[
        sessionIndex
      ].pcc_rule[ruleIndex].flow,
    ];

    const { source, destination } = result;
    if (!destination) return;
    const reordered = Array.from(prevSliceArray);
    const [removed] = reordered.splice(source.index, 1);
    reordered.splice(destination.index, 0, removed);
    prevSliceArray = reordered;
    createSubscriberController.setFieldValue(
      `slice[${sliceIndex}].session[${sessionIndex}].pcc_rule[${ruleIndex}].flow`,
      prevSliceArray
    );
  };

  const handleChangeSst = (value, index) => {
    const currentSlice = createSubscriberController.values.slice;
    const updatedSlice = currentSlice.map((item, ind) =>
      ind === index ? { ...item, sst: value } : item
    );
    createSubscriberController.setFieldValue("slice", updatedSlice);
  };

  useEffect(() => {
    handleValidateForm(createSubscriberController);
  }, [createSubscriberController.values]);

  return (
    <Fragment>
      <Breadcrumbs
        title="Add new subscriber"
        data={[{ title: "Subscribers" }, { title: "Add new subscriber" }]}
      />
      <form
        onSubmit={(e) => {
          e.preventDefault();
          createSubscriberController.handleSubmit();
          handleValidateForm(createSubscriberController);
        }}
      >
        {/* divider */}
        <div
          className={"border-bottom pb-1 mb-1 mt-1"}
          style={{ fontWeight: 900, fontSize: 18 }}
        >
          Subscriber Configuration
        </div>
        <Row>
          {/* imsi */}
          <Col xs="12" className={"mb-1"}>
            <Label for="imsi" style={{ position: "relative" }}>
              IMSI{" "}
              <div
                style={{
                  color: "red",
                  fontSize: 18,
                  position: "absolute",
                  right: -16,
                  top: -2,
                }}
              >
                *
              </div>
            </Label>
            <div className="d-flex align-items-center">
              <Input
                value={createSubscriberController.values.imsi}
                onChange={(e) => {
                  createSubscriberController.setFieldValue(
                    "imsi",
                    formatHelper.toEnglishString(e.target.value)
                  );
                }}
                name="imsi"
                id="imsi"
                type="number"
                className={
                  showValidations && validations.imsi.length > 0
                    ? "form_error"
                    : null
                }
              />
              <Button
                onClick={() => {
                  let array = [...createSubscriberController.values.msisdn];
                  array.push("");
                  createSubscriberController.setFieldValue("msisdn", array);
                }}
                type="button"
                color="success"
                style={{ marginLeft: 16, fontSize: 14, minWidth: 150 }}
                disabled={createSubscriberController.values.msisdn.length > 1}
              >
                Add MSISDN
              </Button>
            </div>
            {showValidations && validations.imsi.length > 0 ? (
              <FormFeedback style={{ display: "block" }}>
                {validations.imsi}
              </FormFeedback>
            ) : null}
          </Col>
          {/* msisdn */}
          <DragDropContext onDragEnd={handleDragEnd}>
            <Droppable droppableId="msisdnList">
              {(provided) => (
                <div {...provided.droppableProps} ref={provided.innerRef}>
                  {createSubscriberController.values.msisdn.map(
                    (item, index) => (
                      <Draggable
                        key={`msisdn-${index}`}
                        draggableId={`msisdn-${index}`}
                        index={index}
                      >
                        {(provided) => (
                          <div
                            className="d-flex align-items-center"
                            ref={provided.innerRef}
                            {...provided.draggableProps}
                          >
                            {createSubscriberController.values.msisdn.length >
                            1 ? (
                              <button
                                style={{
                                  cursor: "grab",
                                  marginRight: 8,
                                  background: "transparent",
                                  border: "none",
                                }}
                                {...provided.dragHandleProps}
                              >
                                <MdDragIndicator fontSize={24} />
                              </button>
                            ) : null}
                            <Col className="mb-1">
                              <Label for={`msisdn_${index + 1}`}>
                                MSISDN {index + 1}
                              </Label>
                              <div
                                style={{
                                  display: "flex",
                                  alignItems: "center",
                                  position: "relative",
                                }}
                              >
                                <Input
                                  name={`msisdn_${index + 1}`}
                                  id={`msisdn_${index + 1}`}
                                  value={item}
                                  className={
                                    index == 0
                                      ? showValidations &&
                                        validations.msisdn_1.length > 0
                                        ? "form_error"
                                        : null
                                      : showValidations &&
                                        validations.msisdn_2.length > 0
                                      ? "form_error"
                                      : null
                                  }
                                  onChange={(e) => {
                                    let numberRegex = /^[0-9+]+$/;
                                    if (e.target.value.length > 0) {
                                      if (numberRegex.test(e.target.value)) {
                                        let array = [
                                          ...createSubscriberController.values
                                            .msisdn,
                                        ];
                                        array[index] = e.target.value;
                                        createSubscriberController.setFieldValue(
                                          "msisdn",
                                          array
                                        );
                                      }
                                    } else {
                                      let array = [
                                        ...createSubscriberController.values
                                          .msisdn,
                                      ];
                                      array[index] = "";
                                      createSubscriberController.setFieldValue(
                                        "msisdn",
                                        array
                                      );
                                    }
                                  }}
                                />
                                <FaRegTrashAlt
                                  onClick={() => {
                                    let array = [
                                      ...createSubscriberController.values
                                        .msisdn,
                                    ];
                                    array = array.filter(
                                      (o, ind) => ind !== index
                                    );
                                    createSubscriberController.setFieldValue(
                                      "msisdn",
                                      array
                                    );
                                  }}
                                  style={{
                                    color: "red",
                                    cursor: "pointer",
                                    position: "absolute",
                                    right: 12,
                                  }}
                                />
                              </div>
                              {index == 0 &&
                              showValidations &&
                              validations.msisdn_1.length > 0 ? (
                                <FormFeedback style={{ display: "block" }}>
                                  {validations.msisdn_1}
                                </FormFeedback>
                              ) : null}
                              {index == 1 &&
                              showValidations &&
                              validations.msisdn_2.length > 0 ? (
                                <FormFeedback style={{ display: "block" }}>
                                  {validations.msisdn_2}
                                </FormFeedback>
                              ) : null}
                            </Col>
                          </div>
                        )}
                      </Draggable>
                    )
                  )}
                  {provided.placeholder}
                </div>
              )}
            </Droppable>
          </DragDropContext>
          {/* subscriber_key */}
          <Col xs="12" sm="7" className={"mb-1"}>
            <Label for="subscriber_key" style={{ position: "relative" }}>
              Subscriber Key (K){" "}
              <div
                style={{
                  color: "red",
                  fontSize: 18,
                  position: "absolute",
                  right: -16,
                  top: -2,
                }}
              >
                *
              </div>
            </Label>
            <Input
              value={createSubscriberController.values.subscriber_key}
              onChange={(e) => {
                createSubscriberController.setFieldValue(
                  "subscriber_key",
                  formatHelper.toEnglishString(e.target.value)
                );
              }}
              name="subscriber_key"
              id="subscriber_key"
              className={
                showValidations && validations.subscriber_key.length > 0
                  ? "form_error"
                  : null
              }
            />
            {showValidations && validations.subscriber_key.length > 0 ? (
              <FormFeedback style={{ display: "block" }}>
                {validations.subscriber_key}
              </FormFeedback>
            ) : null}
          </Col>
          {/* amf */}
          <Col xs="12" sm="5" className={"mb-1"}>
            <Label for="amf" style={{ position: "relative" }}>
              Authentication Management Field (AMF){" "}
              <div
                style={{
                  color: "red",
                  fontSize: 18,
                  position: "absolute",
                  right: -16,
                  top: -2,
                }}
              >
                *
              </div>
            </Label>
            <Input
              value={createSubscriberController.values.amf}
              onChange={(e) => {
                createSubscriberController.setFieldValue(
                  "amf",
                  formatHelper.toEnglishString(e.target.value)
                );
              }}
              name="amf"
              id="amf"
              className={
                showValidations && validations.amf.length > 0
                  ? "form_error"
                  : null
              }
            />
            {showValidations && validations.amf.length > 0 ? (
              <FormFeedback style={{ display: "block" }}>
                {validations.amf}
              </FormFeedback>
            ) : null}
          </Col>
          {/* usim_type */}
          <Col xs="12" sm="5" className={"mb-1"}>
            <Label for="usim_type" className={"d-flex align-items-center"}>
              USIM Type
            </Label>
            <Select
              isClearable={true}
              theme={selectThemeColors}
              closeMenuOnSelect={true}
              placeholder="select option"
              maxMenuHeight={120}
              options={USIM_TYPES}
              className={`react-select`}
              classNamePrefix="select"
              id="usim_type"
              name="usim_type"
              value={createSubscriberController.values.usim_type}
              onChange={(value) => {
                createSubscriberController.setFieldValue("usim_type", value);
              }}
            />
            {createSubscriberController.touched.usim_type &&
            createSubscriberController.errors.usim_type ? (
              <FormFeedback style={{ display: "block" }}>
                {createSubscriberController.errors.usim_type}
              </FormFeedback>
            ) : null}
          </Col>
          {/* operator_key */}
          <Col xs="12" sm="7" className={"mb-1"}>
            <Label for="operator_key" style={{ position: "relative" }}>
              Operator Key (OPc/OP){" "}
              <div
                style={{
                  color: "red",
                  fontSize: 18,
                  position: "absolute",
                  right: -16,
                  top: -2,
                }}
              >
                *
              </div>
            </Label>
            <Input
              value={createSubscriberController.values.operator_key}
              onChange={(e) => {
                createSubscriberController.setFieldValue(
                  "operator_key",
                  formatHelper.toEnglishString(e.target.value)
                );
              }}
              name="operator_key"
              id="operator_key"
              className={
                showValidations && validations.operator_key.length > 0
                  ? "form_error"
                  : null
              }
            />
            {showValidations && validations.operator_key.length > 0 ? (
              <FormFeedback style={{ display: "block" }}>
                {validations.operator_key}
              </FormFeedback>
            ) : null}
          </Col>
          {/* ue_ambr_downlink */}
          <Col xs="12" sm="4" className={"mb-1"}>
            <Label for="ue_ambr_downlink" style={{ position: "relative" }}>
              UE-AMBR Downlink{" "}
              <div
                style={{
                  color: "red",
                  fontSize: 18,
                  position: "absolute",
                  right: -16,
                  top: -2,
                }}
              >
                *
              </div>
            </Label>
            <Input
              value={createSubscriberController.values.ue_ambr_downlink}
              onChange={(e) => {
                createSubscriberController.setFieldValue(
                  "ue_ambr_downlink",
                  formatHelper.toEnglishString(e.target.value)
                );
              }}
              type="number"
              name="ue_ambr_downlink"
              id="ue_ambr_downlink"
              className={
                showValidations && validations.ue_ambr_downlink.length > 0
                  ? "form_error"
                  : null
              }
            />
            {showValidations && validations.ue_ambr_downlink.length > 0 ? (
              <FormFeedback style={{ display: "block" }}>
                {validations.ue_ambr_downlink}
              </FormFeedback>
            ) : null}
          </Col>
          {/* ue_ambr_downlink_unit */}
          <Col xs="12" sm="2" className={"mb-1"}>
            <Label
              for="ue_ambr_downlink_unit"
              className={"d-flex align-items-center"}
            >
              Unit
            </Label>
            <Select
              isClearable={false}
              theme={selectThemeColors}
              closeMenuOnSelect={true}
              placeholder="select option"
              maxMenuHeight={150}
              menuPlacement="top"
              options={UNITS}
              className={`react-select`}
              classNamePrefix="select"
              id="ue_ambr_downlink_unit"
              name="ue_ambr_downlink_unit"
              value={createSubscriberController.values.ue_ambr_downlink_unit}
              onChange={(value) => {
                createSubscriberController.setFieldValue(
                  "ue_ambr_downlink_unit",
                  value
                );
              }}
            />
          </Col>
          {/* ue_ambr_uplink */}
          <Col xs="12" sm="4" className={"mb-1"}>
            <Label for="ue_ambr_uplink" style={{ position: "relative" }}>
              UE-AMBR Uplink{" "}
              <div
                style={{
                  color: "red",
                  fontSize: 18,
                  position: "absolute",
                  right: -16,
                  top: -2,
                }}
              >
                *
              </div>
            </Label>
            <Input
              value={createSubscriberController.values.ue_ambr_uplink}
              onChange={(e) => {
                createSubscriberController.setFieldValue(
                  "ue_ambr_uplink",
                  formatHelper.toEnglishString(e.target.value)
                );
              }}
              type="number"
              name="ue_ambr_uplink"
              id="ue_ambr_uplink"
              className={
                showValidations && validations.ue_ambr_uplink.length > 0
                  ? "form_error"
                  : null
              }
            />
            {showValidations && validations.ue_ambr_uplink.length > 0 ? (
              <FormFeedback style={{ display: "block" }}>
                {validations.ue_ambr_uplink}
              </FormFeedback>
            ) : null}
          </Col>
          {/* ue_ambr_uplink_unit */}
          <Col xs="12" sm="2" className={"mb-1"}>
            <Label
              for="ue_ambr_uplink_unit"
              className={"d-flex align-items-center"}
            >
              Unit
            </Label>
            <Select
              isClearable={false}
              theme={selectThemeColors}
              closeMenuOnSelect={true}
              placeholder="select option"
              maxMenuHeight={150}
              menuPlacement="top"
              options={UNITS}
              className={`react-select`}
              classNamePrefix="select"
              id="ue_ambr_uplink_unit"
              name="ue_ambr_uplink_unit"
              value={createSubscriberController.values.ue_ambr_uplink_unit}
              onChange={(value) => {
                createSubscriberController.setFieldValue(
                  "ue_ambr_uplink_unit",
                  value
                );
              }}
            />
          </Col>
          {/* subscriber_status */}
          <Col xs="12" sm="6" className={"mb-1"}>
            <Label
              for="subscriber_status"
              className={"d-flex align-items-center"}
            >
              Subscriber Status (TS 29.272 7.3.29)
            </Label>
            <Select
              isClearable={true}
              theme={selectThemeColors}
              closeMenuOnSelect={true}
              placeholder="select option"
              maxMenuHeight={150}
              menuPlacement="top"
              options={SUBSCRIBER_STATUS}
              className={`react-select`}
              classNamePrefix="select"
              id="subscriber_status"
              name="subscriber_status"
              value={createSubscriberController.values.subscriber_status}
              onChange={(value) => {
                createSubscriberController.setFieldValue(
                  "subscriber_status",
                  value
                );
              }}
            />
          </Col>
          {/* operator_determined_barring */}
          <Col xs="12" sm="6" className={"mb-1"}>
            <Label
              for="operator_determined_barring"
              className={"d-flex align-items-center"}
            >
              Operator Determined Barring (TS 29.272 7.3.30)
            </Label>
            <Select
              isClearable={true}
              theme={selectThemeColors}
              closeMenuOnSelect={true}
              placeholder="select option"
              maxMenuHeight={150}
              menuPlacement="top"
              options={OPERATOR_DETERMINED_BARRING}
              className={`react-select`}
              classNamePrefix="select"
              id="operator_determined_barring"
              name="operator_determined_barring"
              value={
                createSubscriberController.values.operator_determined_barring
              }
              onChange={(value) => {
                createSubscriberController.setFieldValue(
                  "operator_determined_barring",
                  value
                );
              }}
            />
          </Col>
        </Row>
        {/* divider */}
        <div
          className={
            "border-bottom pb-1 mb-1 mt-3 d-flex justify-content-between"
          }
        >
          <div style={{ fontWeight: 900, fontSize: 18 }}>
            Slice Configurations
          </div>
          <Button
            onClick={() => {
              let array = [...createSubscriberController.values.slice];
              array.push({
                sst: 1,
                sd: "",
                default_indicator: true,
                session: [
                  {
                    dnn_apn: "internet",
                    type: { label: "IPv4v6", value: 3 },
                    qi_qci: { label: "9", value: 9 },
                    arp_priority_level: { label: "8", value: 8 },
                    capability: { label: "Disabled", value: 1 },
                    vulnerability: { label: "Disabled", value: 1 },
                    session_ambr_downlink: "1",
                    session_ambr_downlink_unit: { label: "Gbps", value: 3 },
                    session_ambr_uplink: "1",
                    session_ambr_uplink_unit: { label: "Gbps", value: 3 },
                    ue_ipv4_address: "",
                    ue_ipv6_address: "",
                    smf_ipv4_address: "",
                    smf_ipv6_address: "",
                    pcc_rule: [],
                  },
                ],
              });
              createSubscriberController.setFieldValue("slice", array);
            }}
            size="sm"
            type="button"
            color="success"
            style={{ marginLeft: 16 }}
          >
            Add slice
          </Button>
        </div>
        <DragDropContext onDragEnd={handleDragSlice}>
          <Droppable droppableId="sliceList">
            {(provided) => (
              <div {...provided.droppableProps} ref={provided.innerRef}>
                {createSubscriberController.values.slice.map((item, index) => (
                  <SliceComponent
                    item={item}
                    index={index}
                    createSubscriberController={createSubscriberController}
                    handleChangeSst={handleChangeSst}
                    handleDragSession={handleDragSession}
                    handleDragPccRule={handleDragPccRule}
                    handleDragFlow={handleDragFlow}
                    validations={validations}
                    showValidations={showValidations}
                  />
                ))}
                {provided.placeholder}
              </div>
            )}
          </Droppable>
        </DragDropContext>
        {/* action button */}
        <Col xs="12" className="d-flex justify-content-start mt-3 mb-2">
          <CustomButton
            loading={loadings.createSubscriber}
            type="submit"
            color={"success"}
            size="lg"
          >
            Submit new subscriber
          </CustomButton>
        </Col>
      </form>
    </Fragment>
  );
};
export default NewSubscriber;
